<?php
namespace ZinCelestial\Platform\Audit;use RuntimeException;defined('ABSPATH')||exit;
final class ImmutableAuditLog{public function __construct(private \wpdb $db,private string $table,private int $site_id,private string $key_id='wp-salt-v1'){if($site_id<1)throw new RuntimeException('Invalid audit tenant.');}
 public function append(string $event,array $data,int $actor):string{$safe=array_intersect_key($data,['run'=>1,'operation'=>1,'policy'=>1,'result'=>1,'jti_hash'=>1,'request_id'=>1]);ksort($safe);$this->db->query('START TRANSACTION');try{$prev=(string)$this->db->get_var($this->db->prepare("SELECT entry_hash FROM {$this->table} WHERE site_id=%d ORDER BY sequence_id DESC LIMIT 1 FOR UPDATE",$this->site_id));$record=['actor'=>$actor,'data'=>$safe,'event'=>sanitize_key($event),'key_id'=>$this->key_id,'previous_hash'=>$prev,'site_id'=>$this->site_id,'timestamp'=>gmdate('c')];$payload=wp_json_encode($record,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if($payload===false)throw new RuntimeException('Audit serialization failed.');$hash=hash_hmac('sha256',$payload,wp_salt('secure_auth'));$ok=$this->db->insert($this->table,['site_id'=>$this->site_id,'event'=>$record['event'],'actor_id'=>$actor,'key_id'=>$this->key_id,'payload'=>$payload,'previous_hash'=>$prev,'entry_hash'=>$hash,'created_at'=>current_time('mysql',true)]);if($ok!==1)throw new RuntimeException('Audit append failed.');$this->db->query('COMMIT');return$hash;}catch(\Throwable $e){$this->db->query('ROLLBACK');throw$e;}}
 public function verify(array $rows,callable $key_resolver):bool{$prev='';foreach($rows as $r){if(!hash_equals($prev,(string)$r['previous_hash']))return false;$key=(string)$key_resolver($r['key_id']);$expected=hash_hmac('sha256',$r['payload'],$key);if(!hash_equals($expected,$r['entry_hash']))return false;$prev=$r['entry_hash'];}return true;}}
